import json,time,cv2,numpy as np
from scipy.ndimage import distance_transform_edt,map_coordinates
from rcb_brush import Session,WangBrush
PX=.22185986964255727
TARGET=cv2.imread('/app/target.png',0)<100
D=distance_transform_edt(TARGET)*PX

def plan():
 out=[];floor=.16
 def add(u,v,z):out.append([u,v,z])
 def connect(u,v):
  if out:
   a=np.array(out[-1]);z=a[2];
   for pr in np.arange(z,floor,-.06):add(a[0],a[1],pr)
   for _ in range(12):add(a[0],a[1],floor)
   dist=np.linalg.norm((a[:2]-[u,v])*PX);n=max(1,int(np.ceil(dist/.7)))
   for k in range(1,n+1):
    p=a[:2]+(np.array([u,v])-a[:2])*k/n;add(*p,floor)
   for _ in range(8):add(u,v,floor)
  else:add(u,v,floor)
 # boundary-adjacent loops progressively inwards; offset ~1.3mm at depth .6
 for inset,press in [(1.10,.55),(1.55,.75),(2.10,1.0),(2.70,1.25),(3.4,1.5),(4.2,1.9),(5.2,2.3),(6.3,2.8),(7.8,3.5),(9.5,4.3),(11.5,5.3)]:
  contours,_=cv2.findContours((D>inset).astype(np.uint8),cv2.RETR_LIST,cv2.CHAIN_APPROX_NONE)
  for c in sorted(contours,key=cv2.contourArea,reverse=True):
   c=c[:,0,:].astype(float)
   if len(c)<10:continue
   # closed contours need anticlockwise and clockwise passes to fill both sides of hair root.
   for cc in [c,c[::-1]]:
    connect(*cc[0]);
    for pr in np.arange(floor,press,.06):add(*cc[0],pr)
    for _ in range(8):add(*cc[0],press)
    last=cc[0]
    for pt in np.vstack([cc[1:],cc[:1]]):
     n=max(1,int(np.ceil(np.linalg.norm((pt-last)*PX)/.25)))
     for k in range(1,n+1):add(*(last+(pt-last)*k/n),press)
     last=pt
    # settle pressure shrink in place
    for pr in np.arange(press,floor,-.06):add(*last,pr)
    for _ in range(12):add(*last,floor)
 return np.array(out)

def metrics(ink):
 m=ink>=.5;inter=(m&TARGET).sum();union=(m|TARGET).sum();outside=distance_transform_edt(~TARGET)*PX
 e=m^cv2.erode(m.astype(np.uint8),np.ones((3,3),np.uint8)).astype(bool)
