 return dict(iou=inter/union,recall=inter/TARGET.sum(),precision=inter/max(1,m.sum()),stray=(m&(outside>1)).sum()/TARGET.sum(),boundary_f=2*a*b/(a+b))

def draw(path,name='contour',score=True):
 s=Session('/app/instance.json');s.reset();s.record_start();p=s.primitives()
 p['move_tip']((-.1,.15,.055),speed=.08,settle=10)
 p['move_tip']((-.1,.15,.024),speed=.03,settle=10)
 p['move_tip']((-.1,.15,.055),speed=.06,settle=10)
 def w(pt):
  x,y=s.geo.px_to_world(pt[0],pt[1]);return np.array([x,y,.020-pt[2]/1000])
 wp=np.array([w(pt) for pt in path])
 p['move_tip'](wp[0]+[0,0,.014],speed=.08,settle=12)
 p['move_tip'](wp[0],speed=.005,settle=15)
 t=time.time();last=wp[0]
 for i,pt in enumerate(wp):
  delta=pt-last
